insert into public.tips (id, unit_id, title_en, body_md, status) values
  ('26227d1f-a9b0-5c46-814b-dd7d862ecef8', 'c9686bb1-fe4a-58d4-b91f-601bade129fa', 'Que tenga', 'Something you''re looking for but haven''t found yet takes the subjunctive: **busco un depto que tenga balcón**. Once you''ve found it, it doesn''t: *encontré un depto que tiene balcón*.', 'draft'),
  ('b52a18e2-e627-5862-85be-cadba86191d4', 'c9686bb1-fe4a-58d4-b91f-601bade129fa', 'La garantía', 'Renting in Buenos Aires means the **inmobiliaria** asks for a **garantía** — a relative''s property as a guarantee — and a **contrato**. Some **dueños** don''t take **mascotas**.', 'draft'),
  ('e937bd22-f5be-5f79-9b63-c39f006d5c95', 'fc31544c-c615-5722-9494-5a728b6cf9be', 'Me da bronca', 'Porteños say a feeling *gives* them something: **me da bronca** — *it makes me mad*; **me da vergüenza** — *I''m embarrassed*; **me da lástima** — *I feel sorry*; **me da igual** — *I don''t care*.', 'draft'),
  ('622dd83b-851a-57d2-9dca-b580120220d2', 'fc31544c-c615-5722-9494-5a728b6cf9be', 'Que + subjunctive', 'What causes the feeling follows **que** in the subjunctive: **me da bronca que no conteste**, **me da vergüenza que me vean así**.', 'draft'),
  ('a47564ca-1630-5832-9b7f-0b8120068462', '731a6e56-3586-5647-a6ab-12df3dec98b6', 'Deberías', '**Deberías** — *you should* — is advice with the edges sanded off: **deberías descansar**. **Debería** is *I should* or *he should*: *debería llamar a mi vieja*.', 'draft'),
  ('36795a47-81e7-5de0-bfd5-f8dfc8084e28', '731a6e56-3586-5647-a6ab-12df3dec98b6', 'Estaría bueno', 'The softest porteño suggestion is **estaría bueno** — *it would be nice*: **estaría bueno juntarnos**, **estaría bueno que vengas**. **Habría que** is *we ought to*: *habría que avisarle*.', 'draft'),
  ('b2a9d548-3c48-5353-94cd-0f1e4cdfdbf5', '248f8041-e91e-501f-92e4-301a84aab1d9', 'Que tenga, que avise', 'The subjunctive after **que** for what you haven''t found (*un depto que tenga balcón*) and for what makes you feel something (*me da bronca que no avise*).', 'draft'),
  ('62f485ec-84ef-56a2-984d-23ba30423bfe', '248f8041-e91e-501f-92e4-301a84aab1d9', 'Deberías, estaría bueno', '**Deberías** for advice, **estaría bueno** for a gentle suggestion.', 'draft'),
  ('6671927f-950e-5511-b4d7-c68eaacece32', '0323848f-596e-579a-a7dd-1904e93c1f32', 'Vendrá → vendría', 'Reporting a promise moves it into *would*: «voy» → **dijo que iría**; «te llamo» → **dijo que me llamaría**. Porteños also say **dijo que iba a venir** — same thing.', 'draft'),
  ('3960dc2b-904b-5a87-9ca3-02e2ae3c3968', '0323848f-596e-579a-a7dd-1904e93c1f32', 'Me prometiste', '**Me prometiste que vendrías** — *you promised me you''d come*. And the classic ending: **al final no vino**.', 'draft'),
  ('f0d0b9d1-1dc2-537e-8b97-634f83a3b1b5', '109ff419-4504-54fc-a4e6-0f7e45175049', 'A menos que, siempre y cuando', 'Conditions that haven''t happened take the subjunctive: **a menos que llueva** — *unless it rains*; **siempre y cuando vengas** — *as long as you come*; **en caso de que** — *in case*.', 'draft'),
  ('68fde42c-f91d-5e04-87d5-3b54e0e196fc', '109ff419-4504-54fc-a4e6-0f7e45175049', 'Por si', '**Por si** — *just in case* — is the exception: it keeps the normal verb. **Llevá paraguas por si llueve.** Short version: **por las dudas**.', 'draft'),
  ('fc925c0c-e42b-5a28-81ba-432c1c25033e', '30394d47-559d-52eb-9c24-d6a8bbaeba36', 'Se vende, se alquila', 'Signs say what''s done without saying who: **se vende** — *for sale*; **se alquila** — *for rent*; **se necesita mozo** — *waiter wanted*. More than one thing: **se venden bicis**.', 'draft'),
  ('335c3767-b1f7-50f9-ac59-e107486bfb43', '30394d47-559d-52eb-9c24-d6a8bbaeba36', 'Prohibido', '**Prohibido estacionar** — *no parking*; **prohibido fumar** — *no smoking*. The sign itself is a **cartel**.', 'draft'),
  ('7bc7cb49-45ee-5195-b8b6-8be5a6f0a0a3', 'caff1c3a-1951-5288-a7b5-c4e6b51a503a', 'Dijo que vendría', 'Reported promises go into *would*: **dijo que vendría**, **me prometiste que me llamarías**.', 'draft'),
  ('c365a703-16d2-528c-a92e-16e03e6a091c', 'caff1c3a-1951-5288-a7b5-c4e6b51a503a', 'A menos que, por si', '**A menos que** takes the subjunctive (*a menos que llueva*); **por si** doesn''t (*por si llueve*).', 'draft'),
  ('da454431-0283-5e8b-a68d-ad8b4d5854e7', '7f76ec46-2ddd-507d-8073-89a5df445d05', 'Todo aumenta', 'In Buenos Aires prices **aumentan** so often that the word is small talk: **¿viste cómo aumentó el café?** The **aumento** of your salary never quite keeps up with the **inflación**.', 'draft'),
  ('8af67e04-9d96-5ada-98ea-78bbea30080c', '7f76ec46-2ddd-507d-8073-89a5df445d05', 'Subir, bajar, cobrar', 'Prices **suben** and, now and then, **bajan**. **¿Cuánto te cobraron?** — *how much did they charge you?* A **precio** is a price; *está a buen precio* — *it''s a good price*.', 'draft'),
  ('5ea0dcc7-a99f-5036-9aa2-629ab7f8b899', 'c5abd659-9dd6-54e9-9e4f-6e906e375953', 'Voy entendiendo', '**Ir** + *-ando, -iendo* is something happening bit by bit: **voy entendiendo** — *I''m starting to get it*; **se va llenando** — *it''s filling up*. **De a poco** — *little by little* — goes with it.', 'draft'),
  ('333ca1c2-51cd-51af-b620-1c60102642ac', 'c5abd659-9dd6-54e9-9e4f-6e906e375953', 'Estoy por salir', '**Estar por** + infinitive is *to be about to*: **estoy por salir** — *I''m just about to leave*. A porteño''s *I''m on my way* is often **ya salgo**, which may mean in an hour.', 'draft'),
  ('f82e6975-3c38-5496-851c-8c594e5884fa', '48134c2e-dbea-5e66-9343-0b82457b9fc1', 'Me cae bien', '**Me cae bien** is *I like him* — as a person, not romantically. It works like *gustar*: **me cae bien Juan**, **me caen bien tus amigos**. The first impression: **me cayó mal**.', 'draft'),
  ('2b0c0937-8b3c-514f-8274-775cc7aea148', '48134c2e-dbea-5e66-9343-0b82457b9fc1', 'Nos llevamos bien', '**Llevarse bien** is *to get along*: **me llevo bien con mi hermana**, **nos llevamos re mal**.', 'draft'),
  ('67fd15c6-a49b-5ba9-b35d-7b6893885504', 'c934a093-7470-526c-b293-904cab8a522d', 'Aumentó, subió', '**Todo aumenta**, **el café subió**, **¿cuánto te cobraron?** — the small talk of prices.', 'draft'),
  ('d9a173a8-6a0d-5b0d-97f3-ed5a3f6e3055', 'c934a093-7470-526c-b293-904cab8a522d', 'Voy entendiendo, me cae bien', '**Voy entendiendo** — bit by bit. **Me cae bien** — I like him, as a person.', 'draft'),
  ('8b11e00f-7cc7-55ba-8620-af5bb3193910', '0e125e12-ab8c-5bfd-8a5d-6ae28790e249', 'Ni ahí', '**Ni ahí** — *no way, not even close* — is how a porteño turns something down. **Tal cual** — *exactly* — is how they agree.', 'draft'),
  ('6f7a19a0-4270-5d35-a772-7ff0d5c9059c', '0e125e12-ab8c-5bfd-8a5d-6ae28790e249', 'Es cualquiera', '**Es cualquiera** — *that''s nonsense*. **Flasheaste** — *you''re imagining things*. And a **¡qué lindo!** can be sincere, or ironic when the rain starts.', 'draft')
