  ('aa7d0178-b9eb-51ac-aef1-42854f77d2be', '02764cf9-5a9a-50d1-95f6-bbdc5e4e6015', 'deberías', '{"person":2,"number":"sg","tense":"cond","mood":"ind","voseo":true}'::jsonb, 'you should', null, '731a6e56-3586-5647-a6ab-12df3dec98b6', 1, false, null, null, 'draft'),
